/**
 * Bulk-import ledger and the all-or-nothing write behind `IssueService.importIssues`.
 *
 * One `issue_imports` row per completed upload, keyed by `(org_id, import_key)`.
 * The ledger row, the issues, their labels and any label the file introduced
 * are written in a single transaction, so an import either exists whole or
 * not at all — and a key is only ever "used" by an import that succeeded.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, parseJsonArray } from "./_mappers";
import type { IssueImportRow } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

/** A completed import as the ledger remembers it; `issueIds` is in file order. */
export type IssueImportRecord = {
  readonly id: string;
  readonly orgId: OrgId;
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly importedBy: UserId;
  readonly issueIds: readonly IssueId[];
  readonly createdAt: IsoTimestamp;
};

/** One file row with its assignee already resolved; labels are still names. */
export type ImportedIssueDraft = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
};

export type RecordIssueImportInput = {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedIssueDraft[];
};

function toIssueImport(row: IssueImportRow): IssueImportRecord {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    importedBy: brandId<UserId>(row.importedBy),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
    createdAt: brandStamp(row.createdAt),
  };
}

/** The import this org already completed under `importKey`, if any. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toIssueImport(row) : null;
}

/**
 * Writes a whole import atomically and returns its ledger row.
 *
 * Inside one transaction: the key is re-checked (a concurrent upload of the
 * same key must not import twice — `created: false` hands back the winner's
 * row untouched), label names the org does not have yet are created once
 * each, the issues are numbered in file order after the highest number the
 * project has ever used (archived rows included, as `nextIssueNumber` does),
 * and the ledger row is added. Any failure rolls every one of those back.
 */
export async function recordIssueImport(
  input: RecordIssueImportInput,
): Promise<{ record: IssueImportRecord; created: boolean }> {
  const { orgId, projectId } = input;

  return getDb().transaction((tx) => {
    const existing = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (existing) return { record: toIssueImport(existing), created: false };

    const stamp = toIsoTimestamp(new Date());

    // Label names are matched exactly, and only against this org's labels.
    const labelIdByName = new Map<string, string>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, orgId))
        .all()
        .map((label) => [label.name, label.id]),
    );

    for (const row of input.rows) {
      for (const name of row.labelNames) {
        if (labelIdByName.has(name)) continue;
        const id = newId();
        // No colour given: the column default is the product's default colour.
        tx.insert(labels)
          .values({
            id,
            orgId,
            name,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, id);
      }
    }

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
      )
      .get();
    let number = highest?.value ?? 0;

    const issueIds: IssueId[] = [];

    for (const row of input.rows) {
      number += 1;
      const issueId = newId();

      tx.insert(issues)
        .values({
          id: issueId,
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      // A name repeated inside one row attaches its label once.
      const labelIds = [
        ...new Set(
          row.labelNames.map((name) => labelIdByName.get(name) as LabelId),
