 * ignoring case, against the org's current active members; anything else —
 * a stranger, a member of another org, a removed member — is not an error,
 * the issue is simply left unassigned.
 */
async function draftImportRows(
  input: ImportIssuesInput,
): Promise<readonly ImportedIssueDraft[]> {
  const wantsAssignee = input.rows.some((row) => (row.assigneeEmail ?? null) !== null);
  const userIdByEmail = new Map<string, UserId>();

  if (wantsAssignee) {
    for (const member of await memberRepo.listActiveMemberEmails(input.orgId)) {
      const email = member.email.toLowerCase();
      if (!userIdByEmail.has(email)) userIdByEmail.set(email, member.userId);
    }
  }

  return input.rows.map((row) => {
    const email = row.assigneeEmail ?? null;
    return {
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId:
        email === null ? null : (userIdByEmail.get(email.toLowerCase()) ?? null),
      dueAt: row.dueAt ?? null,
      labelNames: [...new Set(row.labels ?? [])],
    };
  });
}

