 * Imports for one org run one at a time. The steps between "has this key been
 * imported?" and the write are asynchronous, and two uploads of the same key
 * racing through them would both spend the rate allowance before one of them
 * lost; queueing them makes the second a plain replay of the first.
 */
const importQueues = new Map<OrgId, Promise<void>>();

async function inImportQueue<T>(orgId: OrgId, task: () => Promise<T>): Promise<T> {
  const previous = importQueues.get(orgId) ?? Promise.resolve();
  const run = previous.then(task);
  const settled = run.then(
    () => undefined,
    () => undefined,
  );
  importQueues.set(orgId, settled);

  try {
    return await run;
  } finally {
    if (importQueues.get(orgId) === settled) importQueues.delete(orgId);
  }
}

/**
 * Bulk import: every row of an uploaded file becomes an issue, in file order,
 * or none does.
 *
 * The gates are `createIssue`'s — tenant scope, a live project, `issue:create`
 * — and then, per batch rather than per row: the plan's per-project quota for
 * all rows at once, and one unit of the issue-creation rate allowance per row.
 * Only after every gate has passed is anything written, in one transaction,
 * so a refused import leaves no issues, no labels and no trace of its key.
 *
 * `importKey` makes the upload idempotent per org: a key that already
 * completed returns that import's issues with `replayed: true`, whatever the
 * rows now say, and announces nothing.
 *
 * A fresh import publishes a single `issues.imported` instead of an
 * `issue.created` per row. Search, usage and the audit log subscribe to it;
 * notifications and webhooks deliberately do not.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const { record, created } = await inImportQueue(input.orgId, async () => {
    const previous = await issueImportRepo.findIssueImport(
      input.orgId,
      input.importKey,
    );
    if (previous) return { record: previous, created: false };

    const org = requireFound(
      await orgRepo.findOrgById(input.orgId),
      "Organization",
      input.orgId,
    );
    const used = await issueRepo.countIssues(input.orgId, input.projectId);
    if (
      wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)
    ) {
      throw issueQuotaError(org.plan, project);
    }

    // Last gate, because it is the only one with a side effect: an import the
    // quota refuses must not also cost the org its allowance.
    const verdict = await consumeRateLimit(
      input.orgId,
      ISSUE_CREATE_BUCKET,
      input.rows.length,
    );
    if (!verdict.allowed) {
      throw new Error(
        `Issue import rate limit reached; try again after ${verdict.resetAt}`,
      );
    }

    return issueImportRepo.recordIssueImport({
      orgId: input.orgId,
      projectId: project.id,
      importKey: input.importKey,
      authorId: actor.userId,
      rows: await draftImportRows(input),
    });
  });

  // A key is per org, not per project: a replay hands back issues of whichever
  // project the first upload targeted, so the actor must be allowed there too.
  if (!created && record.projectId !== project.id) {
    const original = requireFound(
      await projectRepo.findProjectById(input.orgId, record.projectId),
      "Project",
      record.projectId,
    );
    assertCan(actor, "issue:create", projectResource(original));
  }

  const issues = await issueRepo.findIssuesByIds(input.orgId, record.issueIds);

  if (created) {
    await emit("issues.imported", {
      ...actorEnvelope(actor),
      projectId: record.projectId,
      importKey: record.importKey,
      issueIds: issues.map((issue) => issue.id),
    });
  }

  return {
    importKey: record.importKey,
    projectId: record.projectId,
    issues,
    replayed: !created,
  };
}

/**
 * Turns file rows into insertable drafts. An `assigneeEmail` is matched,
 * ignoring case, against the org's current active members; anything else —
 * a stranger, a member of another org, a removed member — is not an error,
 * the issue is simply left unassigned.
 */
async function draftImportRows(
  input: ImportIssuesInput,
): Promise<readonly ImportedIssueDraft[]> {
  const wantsAssignee = input.rows.some((row) => (row.assigneeEmail ?? null) !== null);
  const userIdByEmail = new Map<string, UserId>();

  if (wantsAssignee) {
    for (const member of await memberRepo.listActiveMemberEmails(input.orgId)) {
      const email = member.email.toLowerCase();
      if (!userIdByEmail.has(email)) userIdByEmail.set(email, member.userId);
    }
  }

  return input.rows.map((row) => {
    const email = row.assigneeEmail ?? null;
    return {
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId:
        email === null ? null : (userIdByEmail.get(email.toLowerCase()) ?? null),
      dueAt: row.dueAt ?? null,
      labelNames: [...new Set(row.labels ?? [])],
    };
  });
}

