      "secret",
    );

    const created = capture("issue.created");
    const imported = capture("issues.imported");
    await usageRepo.recomputeUsage(quiet.org.id);
    const usedBefore = (await usageRepo.getUsage(quiet.org.id)).issuesUsed;

    const result = await issueService.importIssues(
      quiet.actors.member,
      upload(quiet, "announce-key-1", [
        { title: "Quokka migration", assigneeEmail: "admin@announcer.test" },
        { title: "Wombat migration", description: "mentions a platypus" },
      ]),
    );

    expect(created).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: quiet.org.id,
      actorId: quiet.userIds.member,
      projectId: quiet.project.id,
      importKey: "announce-key-1",
      issueIds: result.issues.map((issue) => issue.id),
    });
    expect(result.issues[0]?.assigneeId).toBe(quiet.userIds.admin);

    for (const q of ["Quokka", "platypus"]) {
      const hits = await searchService.search(quiet.actors.member, {
        orgId: quiet.org.id,
        q,
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      });
      expect(hits.total).toBe(1);
    }

    const usage = await usageRepo.getUsage(quiet.org.id);
    expect(usage.issuesUsed).toBe(usedBefore + 2);
    expect((await usageRepo.recomputeUsage(quiet.org.id)).issuesUsed).toBe(usage.issuesUsed);

    const audit = await activityRepo.listActivity({
      orgId: quiet.org.id,
      limit: 100,
      cursor: null,
    });
    const entries = audit.items.filter((event) => event.action.startsWith("issue"));
    expect(entries).toHaveLength(1);
    expect(entries[0]).toMatchObject({
      action: "issues.imported",
      actorId: quiet.userIds.member,
      subjectKind: "project",
      subjectId: quiet.project.id,
      projectId: quiet.project.id,
      metadata: { count: 2, importKey: "announce-key-1" },
    });

    const db = getDb();
    expect(
      db.select().from(notifications).all().filter((row) => row.orgId === quiet.org.id),
    ).toHaveLength(0);
    expect(
      db.select().from(webhookDeliveries).all().filter((row) => row.orgId === quiet.org.id),
    ).toHaveLength(0);
  });
});
